template.script:
odoo.define('payroll_analytics_approval.dashboard_integration', function (require) {
    'use strict';

    var FormController = require('web.FormController');
    var rpc = require('web.rpc');

    FormController.include({

        start: function () {
            var self = this;
            return this._super.apply(this, arguments).then(function () {
                if (self.modelName === 'payroll.dashboard') {
                    self._loadAnalyticsData();
                    self._bindAnalyticsButtons();
                }
            });
        },

        _loadAnalyticsData: function () {
            var self = this;

            // Load pending approvals count
            rpc.query({
                model: 'payroll.analytics',
                method: 'search_count',
                args: [[['state', '=', 'ready']]],
            }).then(function (count) {
                self._updatePendingApprovals(count);
            });

            // Load ready exports count
            rpc.query({
                model: 'payroll.analytics',
                method: 'search_count',
                args: [[['state', '=', 'approved']]],
            }).then(function (count) {
                self._updateReadyExports(count);
            });
        },

        _updatePendingApprovals: function (count) {
            var elements = document.querySelectorAll('[id$="-pending-approvals"]');
            elements.forEach(function (el) {
                el.textContent = count;
                el.className = count > 0 ? 'status-pending' : 'status-ready';
            });
        },

        _updateReadyExports: function (count) {
            var elements = document.querySelectorAll('[id$="-ready-exports"]');
            elements.forEach(function (el) {
                el.textContent = count;
                el.className = count > 0 ? 'status-ready' : 'status-pending';
            });
        },

        _bindAnalyticsButtons: function () {
            var self = this;

            // Bind analytics dashboard buttons
            this.$('.analytics-btn').on('click', function (e) {
                e.preventDefault();
                var country = $(this).data('country');
                self._openAnalyticsDashboard(country);
            });

            // Bind export buttons
            this.$('.export-btn').on('click', function (e) {
                e.preventDefault();
                var country = $(this).data('country');
                self._openBankExport(country);
            });
        },

        _openAnalyticsDashboard: function (country) {
            var self = this;

            // First check if analytics exist for current month
            var currentDate = new Date();
            var firstDay = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
            var lastDay = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0);

            rpc.query({
                model: 'payroll.analytics',
                method: 'search',
                args: [[
                    ['country', '=', country],
                    ['date_from', '>=', firstDay.toISOString().split('T')[0]],
                    ['date_to', '<=', lastDay.toISOString().split('T')[0]]
                ]],
                kwargs: {limit: 1}
            }).then(function (analyticsIds) {
                if (analyticsIds.length > 0) {
                    // Open existing analytics
                    self._openAnalyticsForm(analyticsIds[0]);
                } else {
                    // Generate new analytics
                    self._generateAnalytics(country, firstDay, lastDay);
                }
            });
        },

        _generateAnalytics: function (country, dateFrom, dateTo) {
            var self = this;

            this.$('.analytics-btn').prop('disabled', true).html(' Generating...');

            rpc.query({
                model: 'payroll.analytics',
                method: 'generate_analytics',
                args: [country, dateFrom.toISOString().split('T')[0], dateTo.toISOString().split('T')[0]],
            }).then(function (analyticsId) {
                self._openAnalyticsForm(analyticsId);
            }).finally(function () {
                self.$('.analytics-btn').prop('disabled', false).html(' Open Analytics');
            });
        },

        _openAnalyticsForm: function (analyticsId) {
            this.do_action({
                type: 'ir.actions.act_window',
                res_model: 'payroll.analytics',
                res_id: analyticsId,
                view_mode: 'form',
                view_type: 'form',
                views: [[false, 'form']],
                target: 'current',
                context: {}
            });
        },

        _openBankExport: function (country) {
            // Open bank export wizard
            this.do_action({
                type: 'ir.actions.act_window',
                res_model: 'payroll.bank.export.wizard',
                view_mode: 'form',
                view_type: 'form',
                views: [[false, 'form']],
                target: 'new',
                context: {
                    'default_country': country
                }
            });
        },

        action_open_analytics_dashboard: function () {
            var country = this.getParent().getParent().record.data.country || 'VN';
            this._openAnalyticsDashboard(country);
        },

        action_export_bank_file: function () {
            var country = this.getParent().getParent().record.data.country || 'VN';
            this._openBankExport(country);
        }
    });
});
